toolArgs.file_text:
/* ===== Kanban Board Page ===== */

.loading-message {
    text-align: center;
    padding: 2rem;
    color: #6b7280;
    font-size: 1.1rem;
}

.error-message {
    background: #fef2f2;
    border: 1px solid #fca5a5;
    border-radius: 0.5rem;
    padding: 1rem;
    margin-bottom: 1rem;
    color: #dc2626;
}

.error-message button {
    margin-top: 0.5rem;
    padding: 0.4rem 1rem;
    background: #dc2626;
    color: white;
    border: none;
    border-radius: 0.25rem;
    cursor: pointer;
}

/* ===== Stats Bar ===== */

.stats-bar {
    display: flex;
    gap: 1rem;
    margin-bottom: 1rem;
    flex-wrap: wrap;
}

.stat-item {
    background: #f3f4f6;
    border-radius: 0.5rem;
    padding: 0.75rem 1.25rem;
    display: flex;
    flex-direction: column;
    align-items: center;
    min-width: 80px;
}

.stat-value {
    font-size: 1.5rem;
    font-weight: 700;
    color: #111827;
}

.stat-label {
    font-size: 0.75rem;
    color: #6b7280;
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

.stat-overdue .stat-value {
    color: #dc2626;
}

/* ===== Search Bar ===== */

.search-bar {
    margin-bottom: 1rem;
}

.search-input {
    width: 100%;
    max-width: 400px;
    padding: 0.5rem 0.75rem;
    border: 1px solid #d1d5db;
    border-radius: 0.375rem;
    font-size: 0.95rem;
}

.search-input:focus {
    outline: none;
    border-color: #6366f1;
    box-shadow: 0 0 0 2px rgba(99, 102, 241, 0.2);
}

/* ===== Kanban Board Layout ===== */

.kanban-board {
    display: flex;
    gap: 1rem;
    align-items: flex-start;
    overflow-x: auto;
    padding-bottom: 1rem;
}

/* ===== Kanban Column ===== */

.kanban-column {
    flex: 1;
    min-width: 280px;
    max-width: 380px;
    background: #f9fafb;
    border-radius: 0.5rem;
    border: 1px solid #e5e7eb;
    display: flex;
    flex-direction: column;
}

.column-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #e5e7eb;
}

.column-header h3 {
    margin: 0;
    font-size: 1rem;
    font-weight: 600;
}

.column-count {
    background: #e5e7eb;
    border-radius: 9999px;
    padding: 0.1rem 0.55rem;
    font-size: 0.8rem;
    font-weight: 600;
    color: #374151;
}

.column-body {
    padding: 0.5rem;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    min-height: 60px;
}

.column-footer {
    padding: 0.5rem;
    border-top: 1px solid #e5e7eb;
}

/* ===== Task Card ===== */

.task-card {
    background: white;
    border: 1px solid #e5e7eb;
    border-radius: 0.375rem;
    padding: 0.75rem;
    box-shadow: 0 1px 2px rgba(0, 0, 0, 0.05);
}

.task-card-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    gap: 0.5rem;
    margin-bottom: 0.5rem;
}

.task-title {
    font-weight: 600;
    font-size: 0.9rem;
    color: #111827;
}

.priority-badge {
    font-size: 0.7rem;
    font-weight: 600;
    padding: 0.15rem 0.5rem;
    border-radius: 9999px;
    text-transform: uppercase;
    white-space: nowrap;
}

.priority-high {
    background: #fee2e2;
    color: #dc2626;
}

.priority-medium {
    background: #fef9c3;
    color: #a16207;
}

.priority-low {
    background: #dcfce7;
    color: #16a34a;
}

.task-card-body {
    display: flex;
    justify-content: space-between;
    font-size: 0.8rem;
    color: #6b7280;
    margin-bottom: 0.5rem;
}

.task-card-actions {
    display: flex;
    gap: 0.5rem;
}

.btn-move {
    flex: 1;
    padding: 0.3rem 0.5rem;
    font-size: 0.75rem;
    border: 1px solid #d1d5db;
    border-radius: 0.25rem;
    background: white;
    color: #374151;
    cursor: pointer;
}

.btn-move:hover {
    background: #f3f4f6;
}

/* ===== Add Task Button & Form ===== */

.btn-add-task {
    width: 100%;
    padding: 0.5rem;
    background: transparent;
    border: 1px dashed #d1d5db;
    border-radius: 0.375rem;
    color: #6b7280;
    cursor: pointer;
    font-size: 0.85rem;
}

.btn-add-task:hover {
    background: #f3f4f6;
    color: #374151;
}

.add-task-form {
    display: flex;
    flex-direction: column;
    gap: 0.4rem;
}

.form-group {
    display: flex;
    flex-direction: column;
}

.form-input {
    padding: 0.4rem 0.6rem;
    border: 1px solid #d1d5db;
    border-radius: 0.25rem;
    font-size: 0.85rem;
}

.form-input:focus {
    outline: none;
    border-color: #6366f1;
}

.form-actions {
    display: flex;
    gap: 0.5rem;
    margin-top: 0.25rem;
}

.btn-save {
    flex: 1;
    padding: 0.4rem;
    background: #4f46e5;
    color: white;
    border: none;
    border-radius: 0.25rem;
    cursor: pointer;
    font-size: 0.85rem;
}

.btn-save:hover:not(:disabled) {
    background: #4338ca;
}

.btn-save:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-cancel {
    flex: 1;
    padding: 0.4rem;
    background: white;
    border: 1px solid #d1d5db;
    border-radius: 0.25rem;
    cursor: pointer;
    font-size: 0.85rem;
    color: #374151;
}

.btn-cancel:hover:not(:disabled) {
    background: #f3f4f6;
}

